def _decide_closure_ready(event, judge):
    text = _event_text(event)
    return judge.decide(
        proposition=(
            "Does this assistant message state that the assistant has enough evidence "
            "to close out the investigation, meaning it is ready to close the investigation "
            "before submit_report is invoked, without requiring any claim that a report was already submitted?"
        ),
        evidence=[EvidenceItem(event.id, "output", text)],
        subject_refs=[event.id],
    )

def _assistant_messages_before_submit(run, first_submit_seq):
    seen = set()
    candidates = []
    for event in run.events:
        if event.kind != "message" or event.name != "assistant_message":
            continue
        if event.seq >= first_submit_seq:
            continue
        text = _event_text(event)
        identity = (event.id, event.seq, event.kind, event.name, text)
        if identity in seen:
            continue
        seen.add(identity)
        candidates.append(event)
        if len(candidates) >= MAX_CANDIDATES:
            break
    return candidates

